const ts = require('typescript');
const path = require('path');
const root = process.cwd();
const configPath = ts.findConfigFile(root, ts.sys.fileExists, 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, root);
const program = ts.createProgram({
  rootNames: parsed.fileNames,
  options: { ...parsed.options, noEmit: true },
});
const files = [
  'src/components/CustomDatePicker/CustomDatePicker.styles.ts',
  'src/components/CustomDatePicker/CustomDatePicker.tsx',
  'src/components/SafeView.tsx',
  'src/csxRoutes/MainTabNavigator.tsx',
  'src/csxRoutes/NavigationContainer.tsx',
  'src/csxRoutes/csxRouter.ts',
  'src/i18n/locale/en.ts',
  'src/i18n/locale/jp.ts',
  'src/i18n/locale/ph.ts',
  'src/i18n/locale/th.ts',
  'src/i18n/locale/vn.ts',
  'src/i18n/locale/zh.ts',
  'src/i18n/locale/zh_tw.ts',
  'src/pages/BusinessIncomePage/BusinessIncomePage.styles.ts',
  'src/pages/BusinessIncomePage/BusinessIncomePage.tsx',
  'src/pages/BusinessOverviewNew/BusinessOverviewNew.styles.ts',
  'src/pages/BusinessOverviewNew/BusinessOverviewNew.tsx',
].map((f) => path.resolve(root, f));

const format = (d) => {
  const file = d.file ? path.relative(root, d.file.fileName) : '';
  const pos = d.file && d.start != null ? d.file.getLineAndCharacterOfPosition(d.start) : null;
  const line = pos ? pos.line + 1 : 0;
  const col = pos ? pos.character + 1 : 0;
  const msg = ts.flattenDiagnosticMessageText(d.messageText, '\n');
  return `${file}:${line}:${col} TS${d.code} ${d.category} ${msg}`;
};

let missing = 0;
for (const file of files) {
  const sf = program.getSourceFile(file);
  if (!sf) {
    missing++;
    console.log('MISSING ' + path.relative(root, file));
    continue;
  }
  const semantic = program.getSemanticDiagnostics(sf);
  const syntactic = program.getSyntacticDiagnostics(sf);
  const suggestions = program.getSuggestionDiagnostics(sf);
  const all = [...syntactic, ...semantic, ...suggestions];
  console.log('\n== ' + path.relative(root, file) + ' semantic=' + semantic.length + ' syntactic=' + syntactic.length + ' suggestion=' + suggestions.length);
  for (const d of all) {
    console.log(format(d));
  }
}
console.log('\nMISSING_COUNT ' + missing);
console.log('options.strict ' + parsed.options.strict);
EOF
